(()=>{var c;const o=window.location.hostname,s=window.location.href;console.log("[Flow Content Script] Active on:",o,s);const i=new URLSearchParams(window.location.search),t=i.get("flow_grant")||i.get("token");if(t){console.log("[Flow Content Script] Detected flow_grant in URL. Registering delegated session.");try{sessionStorage.setItem("flow_delegated_session",t),localStorage.setItem("flow_delegated_session",t)}catch{}window.postMessage({source:"flow_session_share",type:"FLOW_SESSION_DELEGATED",token:t},"*")}typeof chrome<"u"&&((c=chrome.runtime)!=null&&c.sendMessage)&&chrome.runtime.sendMessage({type:"GET_ACTIVE_DELEGATED_SESSION",domain:o,origin:window.location.origin},e=>{if(e!=null&&e.session){console.log("[Flow Content Script] Verified active delegated session for domain:",o);const l=e.session.token;if(l){try{sessionStorage.setItem("flow_delegated_session",l)}catch{}window.postMessage({source:"flow_session_share",type:"FLOW_SESSION_READY",domain:o,session:e.session},"*")}if(o.includes("accounts.google.com")&&(s.includes("flow.google.com")||s.includes("flow.google"))){const n=i.get("continue");n&&(n.includes("flow.google.com")||n.includes("flow.google"))&&(console.log("[Flow Content Script] Session active - auto-navigating to Flow destination:",n),window.location.href=n)}}})})();
